(() => {
const esc=escapeHtml;
const ranking2025=[['Tabsen','BR'],['Zdr','BR'],['4i20','BR'],['Conjure','BR'],['Salty','DE'],['Insani','BR'],['Marvywn','BR'],['Invoke','LT'],['Oskar','BR'],['Tamashi','FR'],['T10','BR'],['Bezdarnost','KZ'],['Misiuta','BR'],['Lucky','BR'],['Niko','BR'],['Brizado','BR'],['Helix','BR'],['Fway','BR'],['Hardzera','BR'],['Vat','PT']];
window.registerSearchPlayers?.(ranking2025.map(p=>p[0]));
const key=s=>normalizeText(s).replace(/0/g,'o').replace(/[^a-z0-9]/g,'');
const aliases={tabsen:'tabsenn',conjure:'c0njure',misiuta:'misuuta'};
const findPlayer=name=>players.find(p=>key(p.name)===key(aliases[key(name)]||name));
const playerRow=(entry,i)=>{const p=findPlayer(entry[0]),id=window.getRegisteredPlayerId?.(entry[0]);return `<${p||id?'button':'div'} class="portal-rank-row" ${p?`data-player="${players.indexOf(p)}"`:id?`data-entity-player="${id}"`:''}><span class="portal-place">${i+1}.</span><span class="portal-country">${entry[1]}</span><strong>${esc(window.HBSTV.name(entry[0]))}</strong></${p||id?'button':'div'}>`;};
const left=document.querySelector('.left');
const teams=document.createElement('section');teams.className='portal-widget portal-team-widget';teams.innerHTML=`<div class="portal-widget-heading"><h2>Top 5 times do ano</h2><select id="portal-team-year" aria-label="Ano do ranking de equipes">${window.RANKS_TEAM_YEARS.rankings.map(r=>r.year).sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}</select></div><div id="portal-team-list"></div><a class="portal-widget-footer" href="#acervo/top-1-teams-of-years">Ranking completo ↗</a>`;left.prepend(teams);
function renderTeams(){const year=+document.querySelector('#portal-team-year').value,r=window.RANKS_TEAM_YEARS.rankings.find(r=>r.year===year);document.querySelector('#portal-team-list').innerHTML=r.teams.map(t=>{const c=t.logoCrop;return `<a class="portal-rank-row" href="${window.getTeamProfileHref?.(t.name,year)||'#acervo/top-1-teams-of-years'}" data-portal-team-year="${year}"><span class="portal-place">${t.rank}.</span><span class="portal-team-logo"><img src="${esc(r.sourceImage)}" alt="" style="width:${100/c.w}%;height:${100/c.h}%;left:${-100*c.x/c.w}%;top:${-100*c.y/c.h}%"></span><strong>${esc(t.name)}</strong></a>`;}).join('');}renderTeams();document.querySelector('#portal-team-year').addEventListener('change',renderTeams);
document.addEventListener('click',e=>{const link=e.target.closest('[data-portal-team-year]');if(link)window.selectTeamRankingYear(link.dataset.portalTeamYear);});
const right=document.querySelector('.right');right.querySelector('.spotlight')?.remove();right.querySelector('.section-head')?.remove();
const top20=document.createElement('section');top20.className='portal-widget portal-player-widget';top20.innerHTML=`<div class="portal-widget-heading"><h2>Top 20 jogadores</h2><span>2025 · BCN</span></div>${ranking2025.slice(0,5).map(playerRow).join('')}<details class="portal-ranking-more"><summary>Ver os 20 jogadores</summary>${ranking2025.slice(5).map((e,i)=>playerRow(e,i+5)).join('')}</details><a class="portal-widget-footer" href="#acervo/top-20-players">Histórico por ano ↗</a>`;right.prepend(top20);right.querySelector('#ranking').classList.add('portal-widget');
right.querySelectorAll('.archive-link,.contribute,.section-label').forEach(e=>e.remove());
const news=document.createElement('section');news.id='portal-news';news.innerHTML=`<div class="portal-news-heading"><h2>Novidades</h2><span>COMPETITIVO BLOCK STRIKE</span></div><a class="portal-feature" href="#noticia/top20-2025"><div class="portal-feature-art"><span>TOP 20</span><b>2025</b><i>BCN · RANKING ANUAL</i></div><div><span class="portal-kicker">TEMPORADA 2025 · EDIÇÃO 03 NOV 2026</span><h3>tabsenn no topo. Uma nova era no competitivo.</h3><p>Gustavo conquista o primeiro lugar de 2025. Conheça os jogadores que marcaram a temporada.</p><span class="portal-read">Ler notícia ↗</span></div></a><a class="portal-news-row" href="#noticia/majors-tsl"><span class="portal-news-kind">CIRCUITOS</span><strong>Os Majors da TSL e seus registros históricos</strong><span>TSL ↗</span></a><a class="portal-news-row" href="#noticia/ik-legends-2025"><span class="portal-news-kind">EQUIPES</span><strong>IK Legends lidera o Top 5 de equipes de 2025</strong><span>2025 ↗</span></a><a class="portal-news-row" href="#noticia/awards-2025"><span class="portal-news-kind">AWARDS</span><strong>Os destaques do ano: confira os vencedores das premiações</strong><span>2025 ↗</span></a><a class="portal-news-row" href="#noticia/ranking-2017"><span class="portal-news-kind">HISTÓRIA</span><strong>Top 20 de 2017: SanSey lidera o ranking mundial</strong><span>2017 ↗</span></a><a class="portal-widget-footer" href="#novidades">Todas as novidades ↗</a>`;
document.querySelector('.content').prepend(news);
document.querySelectorAll('a[href="#jogadores"]').forEach(a=>a.href='#acervo/hall-of-fame');
document.querySelector('.side-nav').insertAdjacentHTML('beforeend','<a href="#times">◈ <span>Perfis de equipes</span><b>00</b></a>');document.querySelector('.intro h1').textContent='O competitivo tem história.';
document.querySelector('.intro p').textContent='Rankings, campeonatos e os nomes que fizeram o Block Strike.';
const side=document.querySelector('.side-nav');side.insertAdjacentHTML('beforeend','<a href="#acervo/top-1-teams-of-years">▥ <span>Equipes do ano</span><b>06</b></a><a href="#novidades">▤ <span>Novidades</span><b>07</b></a>');
})();
